w('refusal.NO_SUCH_KNOCK', 'No knock in the inbox answers to this id. Nothing was changed.', note='doorbell, refusal by its code')
w('refusal.KNOCKER_SECRET_WEAK', 'A knocker secret this short could be guessed, letting someone else continue your pseudonym. Use a longer one, or ask the doorbell to make one. Nothing was received. The team can see how often its doorbell turns people away.', note='doorbell, refusal by its code')
w('refusal.KNOCK_DISCARDED', 'This knock was set aside. Move it back to new before bringing it in. Nothing was written.', note='doorbell, refusal by its code')
w('refusal.RATE_IP', "Your material was not received. This team's inbox is not taking any more material from where you are sending it just now. It is a limit on how fast one sender may knock, not a judgment about you or about what you sent, and it lifts on its own shortly — the bound is published beside this message. Nothing was stored and nothing was read, so send the same material again a little later and it will arrive. The team can see how often its doorbell turns people away.", note='doorbell, refusal by its code')
w('refusal.RATE_GLOBAL', "Your material was not received. This team's inbox is not taking any more material from anyone just now. The whole instance is at its limit rather than you — the cap exists so that no one sender can fill the inbox — and it lifts on its own shortly; the bound is published beside this message. Nothing was stored and nothing was read, so send the same material again a little later. The team can see how often its doorbell turns people away.", note='doorbell, refusal by its code')
w('refusal.KNOCK_ENVELOPE_TOO_LARGE', "This team's inbox did not read what you sent, because the request itself is larger than this door accepts. Nothing was stored, nothing was opened, and nothing about your material was judged — its size was read off the request and it stopped there. The size this inbox will read is published beside this message. Send the material again smaller, or as more than one knock, and it will be read. The team can see how often its doorbell turns people away.", note='doorbell, refusal by its code')
w('refusal.KNOCK_PAYLOAD_TOO_LARGE', "This team's inbox read your material and cannot keep it, because it is larger than this inbox stores. That is a fact about how this team has set its Civicsmith up rather than a judgment about what you sent — a team that has configured evidence storage can keep far more — and the size this one can keep is published beside this message. Nothing was stored. Send something smaller, or ask the team's members how to get the whole of it to them. The team can see how often its doorbell turns people away.", note='doorbell, refusal by its code')
w('refusal.KNOCK_EMPTY', "This team's inbox has nothing to keep, because what you sent decoded to no bytes at all. The request itself was well formed and named its content, so this is most likely an empty file or an empty box rather than anything wrong with how you sent it. Nothing was stored. Check what you attached and knock again. The team can see how often its doorbell turns people away.", note='doorbell, refusal by its code')
w('doorbell.stated_per_ip', 'at most {per_ip} knocks from one source in any {window_ms} minutes, estimated by a sliding window', note='doorbell, =statedPerIp')
w('doorbell.stated_global', "at most {global} knocks to this team's inbox in any {window_ms} minutes, estimated by a sliding window", note='doorbell, =statedGlobal')
w('doorbell.received.material_group_inbox', "Your material is in the team's inbox awaiting member review.", note='doorbell, received')
